  "implementation": "def solve(case):\\n    nodes = case['nodes']\\n    core = case['core_distance']\\n    distances = case['distances']\\n    n = len(nodes)\\n    if n == 0:\\n        raise ValueError('no nodes')\\n    edges = []\\n    for u, v, d in distances:\\n        if u not in core or v not in core:\\n            raise ValueError('node missing from core_distance')\\n        mr = max(core[u], core[v], d)\\n        # canonicalize undirected: store smaller first for tie-breaking\\n        if u < v:\\n            edges.append((mr, u, v))\\n        else:\\n            edges.append((mr, v, u))\\n    edges.sort(key=lambda x: (x[0], x[1], x[2]))\\n    parent = {node: node for node in nodes}\\n    rank = {node: 0 for node in nodes}\\n    def find(x):\\n        while parent[x] != x:\\n            parent[x] = parent[parent[x]]\\n            x = parent[x]\\n        return x\\n    def union(x, y):\\n        rx, ry = find(x), find(y)\\n        if rx == ry:\\n            return False\\n        if rank[rx] < rank[ry]:\\n            parent[rx] = ry\\n        elif rank[rx] > rank[ry]:\\n            parent[ry] = rx\\n        else:\\n            parent[ry] = rx\\n            rank[rx] += 1\\n        return True\\n    mst_edges = []\\n    total = 0.0\\n    for mr, u, v in edges:\\n        if union(u, v):\\n            mst_edges.append([u, v, mr])\\n            total += mr\\n            if len(mst_edges) == n - 1:\\n                break\\n    if len(mst_edges) != n - 1:\\n        raise ValueError('graph is not connected or insufficient edges')\\n    return {\\n        'mst_edges': mst_edges,\\n        'total_weight': total\\n    }"
}
